classes.cta-five:
.cta-five {--cta-five-transparency-size: 50px; .cta-five__container-img{ .cta-five__column{ overflow: hidden; will-change: transform; animation-iteration-count: infinite; animation-timing-function: linear;  } .cta-five__column:nth-child(1){ animation-name: vertical-scroll-btt; animation-duration: 24s; } .cta-five__column:nth-child(2){ animation-name: vertical-scroll-ttb; animation-duration: 29s; } .cta-five__column:nth-child(3){ animation-name: vertical-scroll-btt; animation-duration: 33s; }  @media(max-width:991px){ -webkit-mask-image: linear-gradient(to bottom, #000, #000, transparent 0, #000 var(--cta-five-transparency-size)); } }}.cta-five {--cta-five-transparency-size: 50px;

  .cta-five__container-img{

    .cta-five__column{
      overflow: hidden;
      will-change: transform;
      animation-iteration-count: infinite;
      animation-timing-function: linear;

      /* Hardcoded, ALWAYS-ON fallback durations. This guarantees the
         animation runs even if the JS below never executes for any
         reason (blocked script, JS error, disabled execution, etc).
         The JS is a progressive enhancement only - it may replace these
         durations with more precise per-device values, but it never
         controls whether the animation plays. Three different values so
         columns never lock into a synced pattern even without JS. */
    }

    .cta-five__column:nth-child(1){
      animation-name: vertical-scroll-btt;
      animation-duration: 24s;
    }
    .cta-five__column:nth-child(2){
      animation-name: vertical-scroll-ttb;
      animation-duration: 29s;
    }
    .cta-five__column:nth-child(3){
      animation-name: vertical-scroll-btt;
      animation-duration: 33s;
    }

    /* Tablet Styles */
    @media(max-width:991px){
      -webkit-mask-image: linear-gradient(to bottom, #000, #000, transparent 0, #000 var(--cta-five-transparency-size));
    }
  }}

